#!/usr/bin/env node
// AUTO-GENERATED SYNC SCRIPT — copies canonical markdown from ../ko and ../en
// into src/content/docs/<locale>/... for the Starlight build.
// Do NOT hand-edit files under src/content/docs — edit the source in ../ko or ../en instead.
// This script only adds/normalizes Starlight frontmatter; it never touches prose.

import { readFileSync, writeFileSync, mkdirSync, rmSync, readdirSync, existsSync, copyFileSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..", "..");
const SITE_ROOT = join(__dirname, "..");
const OUT_ROOT = join(SITE_ROOT, "src", "content", "docs");

const LOCALES = ["ko", "en"];

// Chapters are grouped into part-N subdirectories purely so the sidebar can
// show Part I/II/III as separate autogenerated groups. Prev/Next still flows
// CH01 -> CH15 in a single sequence because sidebar.order below is a single
// continuously-increasing counter across all three groups.
const PARTS = [
  { dir: "part-1", chapters: ["CH01", "CH02", "CH03", "CH04", "CH05", "CH06"] },
  { dir: "part-2", chapters: ["CH07", "CH08", "CH09"] },
  { dir: "part-3", chapters: ["CH10", "CH11", "CH12", "CH13", "CH14", "CH15"] },
];
const CHAPTERS = PARTS.flatMap((p) => p.chapters);
const CHAPTER_DIR = Object.fromEntries(
  PARTS.flatMap((p) => p.chapters.map((ch) => [ch, p.dir]))
);

function readSource(locale, sub, file) {
  return readFileSync(join(REPO_ROOT, locale, sub, file), "utf8");
}

function listDir(locale, sub) {
  const dir = join(REPO_ROOT, locale, sub);
  if (!existsSync(dir)) return [];
  return readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
}

// Extract the first level-1 "# Title" heading as the page title, and strip it
// from the body (Starlight renders the frontmatter title as the H1 itself).
function extractTitle(md, fallback) {
  const m = md.match(/^#\s+(.+?)\s*$/m);
  if (!m) return { title: fallback, body: md };
  const title = m[1].trim();
  const body = md.slice(0, m.index) + md.slice(m.index + m[0].length);
  return { title, body: body.replace(/^\s+/, "") };
}

function yamlEscape(s) {
  return `"${s.replace(/\\/g, "\\\\").replace(/"/g, '\\"')}"`;
}

function yamlLine(key, value, indent) {
  const pad = "  ".repeat(indent);
  if (value === undefined) return null;
  if (value !== null && typeof value === "object") {
    const nested = Object.entries(value)
      .map(([k, v]) => yamlLine(k, v, indent + 1))
      .filter(Boolean)
      .join("\n");
    return `${pad}${key}:\n${nested}`;
  }
  if (typeof value === "number" || typeof value === "boolean") {
    return `${pad}${key}: ${value}`;
  }
  return `${pad}${key}: ${yamlEscape(String(value))}`;
}

// Images live in <repo>/assets/images and are referenced from the source
// Markdown by relative path (so they also render on GitHub). For the Reader
// they are copied to public/images and the links are rewritten to include
// the site base path.
const BASE = "/pricing-handbook/";
const IMAGES_SRC = join(REPO_ROOT, "assets", "images");
const IMAGES_OUT = join(SITE_ROOT, "public", "images");

if (existsSync(IMAGES_OUT)) rmSync(IMAGES_OUT, { recursive: true, force: true });
if (existsSync(IMAGES_SRC)) {
  mkdirSync(IMAGES_OUT, { recursive: true });
  for (const f of readdirSync(IMAGES_SRC)) {
    copyFileSync(join(IMAGES_SRC, f), join(IMAGES_OUT, f));
  }
}

function rewriteAssetLinks(body) {
  return body.replace(/\]\((?:\.\.\/)+assets\/images\//g, `](${BASE}images/`);
}

function writeGenerated(outPath, frontmatter, body) {
  body = rewriteAssetLinks(body);
  mkdirSync(dirname(outPath), { recursive: true });
  const fmLines = Object.entries(frontmatter)
    .map(([k, v]) => yamlLine(k, v, 0))
    .filter(Boolean)
    .join("\n");
  const header = `---\n${fmLines}\n---\n<!-- AUTO-GENERATED by scripts/sync-content.mjs — do not edit, edit source in ko/ or en/ instead -->\n\n`;
  writeFileSync(outPath, header + body, "utf8");
}

// Clean previous generated output (keep the directory itself, which may hold
// non-generated files like index pages for the locale roots we author here).
if (existsSync(OUT_ROOT)) {
  rmSync(OUT_ROOT, { recursive: true, force: true });
}
mkdirSync(OUT_ROOT, { recursive: true });

for (const locale of LOCALES) {
  // Chapters — single flat sidebar order (CH01..CH15); Part grouping is
  // applied only visually in astro.config.mjs's sidebar, so prev/next still
  // flows CH01 -> CH15 across Part boundaries automatically.
  let order = 1;
  for (const ch of CHAPTERS) {
    const file = `${ch}.md`;
    const raw = readSource(locale, "chapters", file);
    const { title, body } = extractTitle(raw, ch);
    const fm = { title, sidebar: { order: order++ } };
    if (ch === CHAPTERS[0]) fm.prev = false;
    if (ch === CHAPTERS[CHAPTERS.length - 1]) fm.next = false;
    writeGenerated(join(OUT_ROOT, locale, "chapters", CHAPTER_DIR[ch], `${ch}.md`), fm, body);
  }

  // Worksheets
  let wOrder = 1;
  for (const file of listDir(locale, "manual")) {
    const raw = readSource(locale, "manual", file);
    const ch = (file.match(/CH\d\d/) || [file])[0];
    const fallback = `${ch} Worksheet`;
    const { title, body } = extractTitle(raw, fallback);
    writeGenerated(
      join(OUT_ROOT, locale, "manual", file),
      { title, sidebar: { order: wOrder++ } },
      body
    );
  }

  // Examples
  let eOrder = 1;
  for (const file of listDir(locale, "examples")) {
    const raw = readSource(locale, "examples", file);
    const ch = (file.match(/CH\d\d/) || [file])[0];
    const fallback = file.replace(/\.md$/, "");
    const { title, body } = extractTitle(raw, fallback);
    writeGenerated(
      join(OUT_ROOT, locale, "examples", file),
      { title, sidebar: { order: eOrder++ } },
      body
    );
  }
}

// Locale landing pages (index) — generated from the same H1s used for the
// sidebar, so every chapter is an individually clickable link directly in
// the landing body (not just in the sidebar). Mirrors the pattern already
// live on business-planning-handbook: a plain "doc" page (no `template:
// splash`, which would hide the left sidebar/mobile menu), with the full
// chapter list as the actual page content.
function chapterLinkList(locale) {
  const lines = [];
  for (const part of PARTS) {
    const heading = PART_HEADINGS[part.dir][locale];
    lines.push(`### ${heading}`, "");
    for (const ch of part.chapters) {
      const raw = readSource(locale, "chapters", `${ch}.md`);
      const { title } = extractTitle(raw, ch);
      lines.push(`- [${title}](chapters/${part.dir}/${ch.toLowerCase()}/)`);
    }
    lines.push("");
  }
  return lines.join("\n");
}

const PART_HEADINGS = {
  "part-1": { ko: "Part I — 가격전략", en: "Part I — Pricing Strategy" },
  "part-2": { ko: "Part II — 사업타당성 연결", en: "Part II — Feasibility Bridge" },
  "part-3": { ko: "Part III — Pricing Harness", en: "Part III — Pricing Harness" },
};

const LANDING = {
  ko: {
    title: "Pricing Strategy Handbook",
    intro: `가격전략과 Pricing Harness 실행 도구를 하나로 결합한 15개 Chapter 핸드북입니다. 15개 챕터 · 15개 워크시트 · 12개 근거 기반 사례로 구성되어 있습니다.`,
    footerNote: `각 챕터별 실습 워크시트와 사례는 왼쪽 사이드바의 **워크시트 & 사례** 그룹에서 확인할 수 있습니다.`,
    startLink: (firstSlug) => `[CH01부터 시작하기 →](${firstSlug})`,
  },
  en: {
    title: "Pricing Strategy Handbook",
    intro: `A 15-chapter handbook connecting pricing strategy with the Pricing Harness execution engine. 15 Chapters · 15 Worksheets · 12 Source-backed Examples.`,
    footerNote: `Each chapter's worksheet and examples are available in the **Worksheets & Examples** sidebar group.`,
    startLink: (firstSlug) => `[Start with CH01 →](${firstSlug})`,
  },
};

for (const locale of LOCALES) {
  const firstSlug = `chapters/${PARTS[0].dir}/${PARTS[0].chapters[0].toLowerCase()}/`;
  const body = [
    LANDING[locale].intro,
    "",
    chapterLinkList(locale),
    LANDING[locale].footerNote,
    "",
    LANDING[locale].startLink(firstSlug),
    "",
  ].join("\n");
  writeGenerated(join(OUT_ROOT, locale, "index.md"), { title: LANDING[locale].title }, body);
}

// Root landing page: bilingual choice, no internal/operational info.
writeGenerated(
  join(OUT_ROOT, "index.md"),
  { title: "Pricing Strategy Handbook" },
  `Pricing Strategy Handbook — v0.1.0\n\n3 Parts · 15 Chapters · 15 Worksheets · 12 Source-backed Examples\n\n- [한국어](/pricing-handbook/ko/)\n- [English](/pricing-handbook/en/)\n`
);

console.log("[sync-content] Synced ko/en chapters, manual, examples into src/content/docs/");
